import{_ as t,o as d,c as o,a2 as s}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"Hidden debug interfaces","description":"","frontmatter":{},"headers":[],"relativePath":"dev/debug-interfaces.md","filePath":"dev/debug-interfaces.md"}'),a={name:"dev/debug-interfaces.md"};function r(c,e,i,n,l,h){return d(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="hidden-debug-interfaces" tabindex="-1">Hidden debug interfaces <a class="header-anchor" href="#hidden-debug-interfaces" aria-label="Permalink to &quot;Hidden debug interfaces&quot;">​</a></h1><p>The inventory of debugging surfaces that are registered commands but not advertised as user tools: the ~93 test-stub programs, the diag category&#39;s ring-0 self-tests and chipset operations, the registry gates, the live-fix probes, and the per-driver passthrough test faces. Every entry is a real registered program or L1SVC op - type its name at the <code>ush&gt;</code> prompt. For how to <em>read</em> the output, see <a href="./debug-handbook.html">debug-handbook.md</a>; the full op numbering is <a href="./interface-dictionary.html">interface-dictionary.md</a>.</p><h2 id="_1-how-to-run-any-of-these" tabindex="-1">1. How to run any of these <a class="header-anchor" href="#_1-how-to-run-any-of-these" aria-label="Permalink to &quot;1. How to run any of these&quot;">​</a></h2><ul><li>Type the program name at the <code>ush&gt;</code> prompt (they are registry entries, surfaced by <code>help -a</code>).</li><li>Arguments, where noted, are passed exactly like any command (<code>disk_rw_test hda</code>); the wrapper joins argv into the op&#39;s arg line.</li><li>From the host: <code>python3 tools/run_l1_per_app.py</code> boots the ISO once per program and records each output (fresh process table per row); <code>tools/run_fix4_regression.py</code> runs the fixed battery (see <a href="./e2e-suites.html">e2e-suites.md</a>).</li><li>The service side owns the grammar: for l1svc-wrapped apps the program is a transparent pipe - a &quot;hidden&quot; flag is one that the registry hint never shows but the service parses.</li></ul><h2 id="_2-test-stub-programs-93" tabindex="-1">2. Test-stub programs (~93) <a class="header-anchor" href="#_2-test-stub-programs-93" aria-label="Permalink to &quot;2. Test-stub programs (~93)&quot;">​</a></h2><p>Grouped by what they exercise. &quot;Run&quot; is the invocation; anything without arguments is a bare name.</p><h3 id="_2-1-ota-update-pipeline-11-config-test" tabindex="-1">2.1 OTA / update pipeline (11 + config_test) <a class="header-anchor" href="#_2-1-ota-update-pipeline-11-config-test" aria-label="Permalink to &quot;2.1 OTA / update pipeline (11 + config_test)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Program</th><th>Tests</th><th>Run</th></tr></thead><tbody><tr><td><code>ab_partition_test</code></td><td>A/B slot + flag semantics</td><td>bare</td></tr><tr><td><code>checkupdate_test</code></td><td>update-check unit test</td><td>bare</td></tr><tr><td><code>update_check_test</code></td><td>check stage unit test</td><td>bare</td></tr><tr><td><code>update_download_test</code></td><td>download stage unit test</td><td>bare</td></tr><tr><td><code>update_install_test</code></td><td>install stage unit test</td><td>bare</td></tr><tr><td><code>update_local_test</code></td><td>offline package install</td><td>bare</td></tr><tr><td><code>update_pkg_test</code></td><td>package manifest/checksum</td><td>bare</td></tr><tr><td><code>update_rollback_test</code></td><td>rollback stage unit test</td><td>bare</td></tr><tr><td><code>update_status_test</code></td><td>status stage unit test</td><td>bare</td></tr><tr><td><code>update_verify_test</code></td><td>SHA256 verify stage</td><td>bare</td></tr><tr><td><code>real_update_test</code></td><td>the full real flow</td><td>bare</td></tr><tr><td><code>config_test</code></td><td>/etc config backend</td><td>bare</td></tr></tbody></table><p>Drivers: <code>tools/make_update_pkg.sh</code> (package), the E2E <code>tools/fix1_checkupdate_e2e.py</code>.</p><h3 id="_2-2-block-storage-8" tabindex="-1">2.2 Block / storage (8) <a class="header-anchor" href="#_2-2-block-storage-8" aria-label="Permalink to &quot;2.2 Block / storage (8)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Program</th><th>Tests</th><th>Run</th></tr></thead><tbody><tr><td><code>ahci_test</code></td><td>AHCI port read</td><td>bare</td></tr><tr><td><code>nvme_test</code></td><td>NVMe namespace read</td><td>bare</td></tr><tr><td><code>ata_dma_test</code></td><td>ATA bus-master DMA vs PIO timing</td><td>bare</td></tr><tr><td><code>virtio_blk_test</code></td><td>virtio-blk round trip</td><td>bare</td></tr><tr><td><code>disk_rw_test</code></td><td>raw sector write/read/compare</td><td><code>disk_rw_test &lt;device&gt;</code></td></tr><tr><td><code>partition_test</code></td><td>partition scan</td><td><code>partition_test [device]</code></td></tr><tr><td><code>fs_mount_test</code></td><td>format + mount round trip</td><td><code>fs_mount_test &lt;device&gt;</code> (<strong>formats it</strong>)</td></tr><tr><td><code>real_hw_test</code></td><td>real hardware disk + NIC survey</td><td>bare</td></tr></tbody></table><h3 id="_2-3-nic-drivers-10" tabindex="-1">2.3 NIC drivers (10) <a class="header-anchor" href="#_2-3-nic-drivers-10" aria-label="Permalink to &quot;2.3 NIC drivers (10)&quot;">​</a></h3><p><code>e1000e_test</code>, <code>igb_test</code>, <code>ixgbe_test</code>, <code>bcm57xx_test</code>, <code>rtl810x_test</code>, <code>rtl8125_test</code>, <code>rtl8139_test</code>, <code>rtl8168_test</code>, <code>nic_rw_test</code> (frame loopback), <code>other_nic_test</code> (best-effort family detect). All bare. These are the <em>direct passthrough</em> debug faces of the per-family drivers - each prints that driver&#39;s own register/link/MAC state, not a generic summary.</p><h3 id="_2-4-audio-8" tabindex="-1">2.4 Audio (8) <a class="header-anchor" href="#_2-4-audio-8" aria-label="Permalink to &quot;2.4 Audio (8)&quot;">​</a></h3><p><code>hda_test</code>, <code>ac97_test</code>, <code>sb16_test</code>, <code>es1370_test</code>, <code>virtio_snd_test</code>, <code>usb_audio_test</code> (per-driver 500 ms tone selftests; hda/ac97/virtio at 48000, sb16/es1370 at 44100), <code>audio_rw_test</code> (PCM loopback, 48 KB buffer), <code>sample_rate_test</code> (caps-bitmap vs set_rate negotiation; honest SKIPPED with no cards; HDA+44100 reports the caps bit only under QEMU). All bare.</p><h3 id="_2-5-usb-7" tabindex="-1">2.5 USB (7) <a class="header-anchor" href="#_2-5-usb-7" aria-label="Permalink to &quot;2.5 USB (7)&quot;">​</a></h3><p><code>usb_core_test</code> (enumeration + control transfers), <code>usb_hotplug_test</code> (connect/disconnect, extra args), <code>usb_hub_test</code> (external hubs), <code>usb_kbd_test</code> (HID keyboard), <code>usb_mouse_test</code> (HID pointer), <code>usb_serial_test</code> (CDC-ACM), <code>usb_storage_test</code> (MSC BOT - registers block devices). All bare.</p><h3 id="_2-6-camera-legacy-ports-6" tabindex="-1">2.6 Camera + legacy ports (6) <a class="header-anchor" href="#_2-6-camera-legacy-ports-6" aria-label="Permalink to &quot;2.6 Camera + legacy ports (6)&quot;">​</a></h3><p><code>uvctest</code> (UVC capture), <code>scsitest</code> (SCSI over block layer, LSI 53C895A), <code>gameporttest</code>, <code>paralleltest</code> (SPP bytes), <code>irtest</code> (NEC/RC5/RC6/SIRC), <code>touchtest</code> (i2c-hid gestures). All bare.</p><h3 id="_2-7-power-paths-4" tabindex="-1">2.7 Power paths (4) <a class="header-anchor" href="#_2-7-power-paths-4" aria-label="Permalink to &quot;2.7 Power paths (4)&quot;">​</a></h3><p><code>poweroff_test</code>, <code>suspend_test</code> (real ACPI S3), <code>halt_test</code>, <code>reboot_test</code> - each exercises the REAL path and can end the session (the power wizard warns + confirms before running them; halt/reboot tests honestly SKIP live observation).</p><h3 id="_2-8-display-cjk-5" tabindex="-1">2.8 Display / CJK (5) <a class="header-anchor" href="#_2-8-display-cjk-5" aria-label="Permalink to &quot;2.8 Display / CJK (5)&quot;">​</a></h3><p><code>chinesetest</code>, <code>font-test</code>, <code>encoding-test</code>, <code>ime-test</code> (engine + session battery: phrase/paging/digit-pick protocol assertions), <code>tui-test</code> (TUI selftest verdict block, ~4.4 KiB). All bare.</p><h3 id="_2-9-kernel-core-self-tests-16" tabindex="-1">2.9 Kernel core self-tests (16+) <a class="header-anchor" href="#_2-9-kernel-core-self-tests-16" aria-label="Permalink to &quot;2.9 Kernel core self-tests (16+)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Program</th><th>Tests</th></tr></thead><tbody><tr><td><code>memtest</code></td><td>memory service battery</td></tr><tr><td><code>heaptest</code></td><td>heap stress (alloc/free/coalesce)</td></tr><tr><td><code>heapbounds</code></td><td>heap boundary conditions</td></tr><tr><td><code>fstest</code></td><td>VFS stress</td></tr><tr><td><code>vmtest</code></td><td>VMM unit test</td></tr><tr><td><code>vmkernelpt</code></td><td>kernel page-table dump</td></tr><tr><td><code>vmmap</code></td><td>address-space map dump</td></tr><tr><td><code>cr3test</code></td><td>CR3 register audit</td></tr><tr><td><code>pftest</code></td><td>page-fault handler</td></tr><tr><td><code>pmmrace</code></td><td>PMM alloc/free race detector</td></tr><tr><td><code>irqabitest</code></td><td>IRQ-entry ABI probe (rsp mod 16, DF=0)</td></tr><tr><td><code>msitest</code></td><td>MSI/MSI-X vector delivery</td></tr><tr><td><code>timer</code></td><td>soft timers</td></tr><tr><td><code>synctest</code></td><td>spinlock/sem/mutex/cond</td></tr><tr><td><code>multi</code></td><td>3 interleaved task wake test</td></tr><tr><td><code>spawn</code></td><td>background spawn demo</td></tr><tr><td><code>exc</code></td><td>exception self-test report (shares the boot counter)</td></tr><tr><td><code>nice</code></td><td>priority demo - <code>nice &lt;tid&gt; &lt;prio 0..31&gt;</code></td></tr></tbody></table><p>Plus the recovery pair <code>crashtest</code> (fault injection, see <a href="./debug-handbook.html">debug-handbook.md</a> 5.1) and <code>dumpinfo</code>, the crypto pair <code>cryptotest</code>/<code>dhtest</code>, <code>l1test</code> (job/IPC/dynlink), and the net tests <code>nf_test</code>/<code>tcpcc_test</code>/<code>tcptest</code>/<code>dnstest</code>.</p><h3 id="_2-10-ring-3-extension-family-flat-programs-tag-l1" tabindex="-1">2.10 Ring-3 extension family (flat programs, tag l1) <a class="header-anchor" href="#_2-10-ring-3-extension-family-flat-programs-tag-l1" aria-label="Permalink to &quot;2.10 Ring-3 extension family (flat programs, tag l1)&quot;">​</a></h3><p>Kernel-surface probes compiled as flat legacy programs:</p><p><code>fork_test</code>, <code>exec_test</code>, <code>fdref_test</code>, <code>pipe_test</code>, <code>select_test</code>, <code>select_zero_test</code>, <code>signal_test</code>, <code>sigsegv_test</code>, <code>sse_test</code> (FPU state across switches), <code>stackovf</code> (user stack guard), <code>int3_user</code> (#BP from ring 3), <code>priv_test</code> (IOPB deny-all - ring-3 port access must fault), <code>pf_test</code>, <code>p3_test</code> (priority), <code>mmap_test</code>, <code>mmap_multi</code>, <code>mprotect_test</code>, <code>g6_test</code> (process group; async tally <code>failed tests = 0</code>), <code>g6_exec_a</code>, <code>g6_exec_b</code>, <code>g6_oom</code>, <code>g7mmap</code> (BUG-0281), and the dynamic-link family <code>pie_test</code>, <code>reloc_test</code>, <code>so_test</code>, <code>dlsym_test</code>, <code>dyn_hello</code>, <code>main_dyn</code>, plus <code>hello</code>, <code>loop</code> (job test target) and <code>badapp</code> (intentionally misbehaving - the canary class for exception kills).</p><h3 id="_2-11-self-verifying-help-tests-3-registry-gates" tabindex="-1">2.11 Self-verifying help tests (3 registry gates) <a class="header-anchor" href="#_2-11-self-verifying-help-tests-3-registry-gates" aria-label="Permalink to &quot;2.11 Self-verifying help tests (3 registry gates)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Program</th><th>Asserts</th></tr></thead><tbody><tr><td><code>help_default_test</code></td><td>the default listing&#39;s count/shape</td></tr><tr><td><code>help_a_test</code></td><td>the A-Z ordering invariant</td></tr><tr><td><code>help_wp_test</code></td><td>the work-package grouping of the LIVE registry text</td></tr></tbody></table><p>They parse the registry text itself (the same <code>L1SVC L1/APPS</code> rendering <code>help</code> uses), so they double as runtime regression gates for the generated <code>OC_USERPROGS[]</code> table.</p><h3 id="_2-12-live-fix-probes-1" tabindex="-1">2.12 Live-fix probes (1) <a class="header-anchor" href="#_2-12-live-fix-probes-1" aria-label="Permalink to &quot;2.12 Live-fix probes (1)&quot;">​</a></h3><p><code>p2test &lt;utf8|read0|pipe&gt;</code>:</p><ul><li><code>utf8</code> pushes 174 hanzi (522 bytes, ONE syscall) through both write paths (console + serial encoding);</li><li><code>read0</code> checks POSIX <code>read(0, buf, 0) == 0</code>;</li><li><code>pipe</code> hammers pipe slot-reuse for 100 rounds.</li></ul><p>Driven over the QEMU serial console by <code>tools/wp_p2_batch_a_test.py</code> (batch A live probes: read0 #14, pipe slot-leak #9).</p><h2 id="_3-the-diag-category-s-hidden-depth-39-ops" tabindex="-1">3. The diag category&#39;s hidden depth (39 ops) <a class="header-anchor" href="#_3-the-diag-category-s-hidden-depth-39-ops" aria-label="Permalink to &quot;3. The diag category&#39;s hidden depth (39 ops)&quot;">​</a></h2><p>Beyond the vitals (1-8), two groups the casual user never meets:</p><ul><li><strong>G9 ring-0 self-tests (ops 9-26)</strong>: cr3test, exc, pftest, pmmrace, vmtest, vmkernelpt, vmmap, memtest, heaptest, heapbounds, irqabitest, timer, msitest, spawn, multi, nice, synctest, fstest - same bodies as the apps above, reachable through L1SVC without the wrapper program. Five of them (vmmap/pftest/cr3test/vmkernelpt) run inside a <strong>switch-to-kernel-AS wrap</strong>: their v2.2.0 semantics depended on the kernel address space being current, so the dispatcher recreates that context from the ring-3 syscall and restores the spawner&#39;s AS before returning.</li><li><strong>G10 chipset operations (ops 27-39)</strong>: acpi, acpidev, acpipow, acpitest (AML parser), pcidump (<code>pcidump &lt;bus:dev.fn&gt;</code> e.g. <code>0:1f.3</code> - full config space), pcibars, pcie, i2cdetect, i2cget (<code>i2cget &lt;bus&gt; &lt;addr&gt; [reg]</code>, hex), i2cset (<code>i2cset &lt;bus&gt; &lt;addr&gt; &lt;reg&gt; &lt;val&gt;</code>), i2ctest, smbus, smbustest (byte/word/block round-trips).</li></ul><h2 id="_4-hidden-parameters-worth-knowing" tabindex="-1">4. Hidden parameters worth knowing <a class="header-anchor" href="#_4-hidden-parameters-worth-knowing" aria-label="Permalink to &quot;4. Hidden parameters worth knowing&quot;">​</a></h2><p>The registry hint never shows these; the service parses them:</p><table tabindex="0"><thead><tr><th>Command</th><th>Hidden arg</th><th>Effect</th></tr></thead><tbody><tr><td><code>top</code></td><td><code>-n N</code></td><td>refresh N times (1..10 clamped), 1 s apart</td></tr><tr><td><code>ln</code></td><td><code>-s &lt;target&gt; &lt;linkpath&gt;</code></td><td>symlink instead of hard link</td></tr><tr><td><code>sed</code></td><td><code>s/old/new/[g]</code>, <code>-n Np</code>, <code>Nd</code></td><td>substitute / print Nth / delete Nth</td></tr><tr><td><code>p2test</code></td><td><code>utf8 | read0 | pipe</code></td><td>probe selector (above)</td></tr><tr><td><code>health</code></td><td><code>watch</code> / <code>export [path]</code></td><td>different L1SVC ops</td></tr><tr><td>8 mega-apps</td><td><code>direct</code></td><td>skip the literal word, verbatim passthrough</td></tr><tr><td><code>help</code></td><td><code>-a</code> / <code>--all</code>, <code>-w</code> / <code>--wp</code></td><td>full A-Z / grouped listing</td></tr><tr><td><code>update</code></td><td><code>status</code>, <code>--status</code>, <code>--local &lt;path&gt;</code>, <code>local &lt;path&gt;</code></td><td>status view / offline install</td></tr><tr><td><code>dns</code></td><td><code>[aaaa|cname|mx|txt|ns|srv]</code></td><td>record-type selector</td></tr><tr><td><code>wget</code></td><td><code>https://...</code> or 3-arg <code>host port path</code></td><td>TLS path / legacy positional form</td></tr><tr><td><code>ssh</code></td><td><code>[port=2222] [user=oc] [password=oc|&quot;-&quot;]</code></td><td><code>-</code> = publickey via /etc/ssh_client_key</td></tr><tr><td><code>ime</code></td><td><code>-i</code></td><td>interactive pinyin compose line (digits pick, space = first, PgUp/PgDn or -/=/= page, Backspace drops a letter, Enter commits raw, Esc cancels)</td></tr><tr><td><code>dmesg</code></td><td><code>[N]</code></td><td>line count 1..1024 (default 30)</td></tr><tr><td><code>uname</code></td><td><code>[-a]</code></td><td>full identity string</td></tr><tr><td><code>serial_encoding</code></td><td><code>[utf8|gbk]</code></td><td>the COM1 tee encoding</td></tr><tr><td><code>sleep</code></td><td>fractional seconds</td><td><code>sleep 0.5</code> = 500 ms delay (NOT suspend)</td></tr></tbody></table><h2 id="_5-nic-passthrough-faces-wifi-bt" tabindex="-1">5. NIC passthrough faces (wifi / bt) <a class="header-anchor" href="#_5-nic-passthrough-faces-wifi-bt" aria-label="Permalink to &quot;5. NIC passthrough faces (wifi / bt)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Modes</th></tr></thead><tbody><tr><td><code>wifi</code></td><td>bare = adapter + family registry status; <code>wifi scan</code> = passive beacon scan (honest &quot;no radio&quot; under QEMU); <code>wifi test</code> = 802.11 core + per-family selftest (families without hardware listed by name); <code>wifi sdio</code> = SDHCI bus state + selftest</td></tr><tr><td><code>bt</code></td><td>bare = transport + controller status; <code>bt usb</code> = HCI-USB transport; <code>bt uart</code> = H4 UART transport; <code>bt test</code> = flow selftest (real E2E over COM2 H4 bytes into <code>tools/bt_test_peer.py</code>)</td></tr></tbody></table><h2 id="_6-usb-test-ops-the-9-op-debug-face" tabindex="-1">6. USB test ops (the 9-op debug face) <a class="header-anchor" href="#_6-usb-test-ops-the-9-op-debug-face" aria-label="Permalink to &quot;6. USB test ops (the 9-op debug face)&quot;">​</a></h2><p>Cat 17 exposes the whole USB stack&#39;s self-tests as first-class ops: <code>usb</code> (status), <code>usbdev [slot]</code> (per-device detail), then <code>usb_core_test</code>, <code>usb_kbd_test</code>, <code>usb_mouse_test</code>, <code>usb_storage_test</code>, <code>usb_serial_test</code>, <code>usb_hotplug_test [...]</code>, <code>usb_hub_test</code>. The kernel-side poll thread (<code>driver_usb_poll_start</code>) is started in kmain and stays resident.</p><h2 id="_7-boot-time-self-tests-not-commands" tabindex="-1">7. Boot-time self-tests (not commands) <a class="header-anchor" href="#_7-boot-time-self-tests-not-commands" aria-label="Permalink to &quot;7. Boot-time self-tests (not commands)&quot;">​</a></h2><p>Two run before the shell exists - their lines appear in every boot log:</p><ul><li><code>l1_ext_self_test()</code> - &quot;WP-01 ext self-test: N/4 points reachable&quot; (probes the 4 extension points: fb access, renderer, font engine, console hook).</li><li><code>arch_exc_tests()</code> - &quot;exception self-test: N/3 (#DE/#UD/#PF) caught, kernel alive&quot; - shares its pass counter with the <code>exc</code> command.</li></ul><h2 id="_8-the-registry-gates-that-keep-this-honest" tabindex="-1">8. The registry gates that keep this honest <a class="header-anchor" href="#_8-the-registry-gates-that-keep-this-honest" aria-label="Permalink to &quot;8. The registry gates that keep this honest&quot;">​</a></h2><ul><li><code>make userprogs-check</code> - fails <code>make dist</code> when any l1apps source / interface header / i18n json is &gt; 2 s newer than the generated <code>userprogs_data.h</code>.</li><li><code>tools/run_fix4_regression.py</code> check 6 - the registry floor: <code>help -a</code> must list &gt;= 276 programs (measured 284).</li><li><code>help_*_test</code> (section 2.11) - runtime shape assertions.</li><li><code>tools/gen_api_docs.py</code> - regenerates <code>docs/data/*.json</code> and the 292 command pages from the <em>live</em> <code>help -a</code> capture, tolerating serial-echo overlap (the <code>[tag]</code> brackets are optional because an echo overlap can eat the leading <code>&quot;e&quot;</code> of <code>&quot;ega]&quot;</code>).</li></ul>',51)])])}const b=t(a,[["render",r]]);export{u as __pageData,b as default};
